/// The `message` member of a synthetic error shape whose wire code is chosen at
/// runtime ([`Unmodeled`]).
static UNMODELED_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#UnmodeledError$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message");

/// Schema for a synthetic error shape whose wire code is chosen at runtime.
///
/// In the `smithy.framework` namespace for the same reason as the two above: the shape
/// is not in any service's model, so it must not collide with a modeled one. Only the
/// `message` member is on the wire; the code and the status travel on [`Unmodeled`].
pub static UNMODELED_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#UnmodeledError",
        "smithy.framework",
        "UnmodeledError",
    ),
    ShapeType::Structure,
    &[&UNMODELED_MESSAGE],
);

/// A rejection whose wire error code this service's model does not declare.
///
/// S3's model omits failures its REST API documents, and they are answered through this
/// one channel so the code and status on the wire are the ones S3 sends. The bucket
/// subresource operations are the case it was added for: `PutBucketPolicy`,
/// `GetBucketPolicy`, `PutBucketTagging` and `GetBucketTagging` declare NO errors in the
/// model, yet S3 answers `NoSuchBucket` (404), `NoSuchBucketPolicy` (404),
/// `NoSuchTagSet` (404) and `MalformedPolicy` (400) on them; the object-storage loop
/// uses it for `BucketNotEmpty` (409), `InvalidArgument` (400), `EntityTooLarge` (400),
/// `BadDigest` (400), `ServiceUnavailable` (503) and `InternalError` (500). A client
/// branches on the code, so the code has to be the one S3 sends.
#[derive(Debug, Clone)]
pub struct Unmodeled {
    /// The wire error code (`<Code>` on restXml).
    pub code: &'static str,
    /// The HTTP status this rejection is rendered with.
    pub status: u16,
    /// Why the request was refused.
    pub message: String,
}

impl std::fmt::Display for Unmodeled {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.code, self.message)
    }
}

impl std::error::Error for Unmodeled {}

impl SerializableStruct for Unmodeled {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&UNMODELED_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

/// A rejection the BOUNDARY answers, with the DETAIL members its error class carries.
///
/// The refusal of a value the framework's own validating walk rejected is worded through
/// [`smithy_server_runtime::Service::override_refusal`], which chooses the code and the
/// message and nothing else — so a document that also names the argument it rejected is
/// written from here instead, by the one renderer that can
/// (`crate::service::EmulatedService::detailed_refusal`). The code and the status travel with
/// that renderer, exactly as they do for [`Unmodeled`].
#[derive(Debug, Clone)]
pub struct UnmodeledWithDetail {
    /// Why the request was refused.
    pub message: String,
    /// What the refusal is ABOUT, written after the message — the order S3's document
    /// carries its members in.
    pub detail: ErrorDetail,
}

impl SerializableStruct for UnmodeledWithDetail {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&UNMODELED_MESSAGE, self.message.as_str())?;
        self.detail.serialize_into(s)
    }
}

/// A rejection the BOUNDARY answers whose error class carries NO detail member: the
/// `<Message>` alone, beside the `<Code>` and the request-correlation elements the envelope
/// itself writes.
///
/// Rendered through this service's own serializer for the reason
/// `crate::service::EmulatedService::worded_refusal` gives — the ids an S3 response is named
/// by are this service's, and the generic renderer behind the wording seam mints its own —
/// so the code and the status travel with that renderer exactly as they do for
/// [`UnmodeledWithDetail`].
#[derive(Debug, Clone)]
pub struct UnmodeledMessage {
    /// Why the request was refused.
    pub message: String,
}

impl SerializableStruct for UnmodeledMessage {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&UNMODELED_MESSAGE, self.message.as_str())
    }
}

/// The `message` member written for a MODELED error whose own shape declares none.
///
/// Same shape as the three synthetic members above — the member name Smithy uses
/// (`message`) with the `Message` element name S3's XML error document carries — so the
/// one value renders as `<Message>` on this service's restXml wire.
static DOCUMENTED_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#DocumentedErrorMessage$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message");

/// The `<Message>` S3 sends for each error code this service's model declares.
///
/// Every error shape in `com.amazonaws.s3` declares no `message` member, yet S3's error
/// document always carries one, and for these codes the text is a fixed, documented
/// constant rather than anything derived from the request — so it belongs here, once,
/// instead of in each handler.
///
/// Sources, per row:
///
/// * the code's entry in AWS's S3 *Error responses* `ErrorCodeList`
///   (<https://docs.aws.amazon.com/AmazonS3/latest/API/ErrorResponses.html#ErrorCodeList>),
///   which publishes the exact text, for the five rows marked `[ErrorCodeList]`; and
/// * otherwise the error shape's own `@documentation` in this service's Smithy model
///   (`smithy_query(query="shape",shape="<Code>",
///   model_path="services/service-com-amazonaws-s3-amazons3/smithy-model/com-amazonaws-s3-amazons3.json")`),
///   HTML stripped — the sentence the model states for that condition.
///
/// `tests/all/error_message_envelope.rs` re-derives the key set from the model and fails
/// if a row is stale or an error shape the model declares has no row, so a model update
/// that adds an error code cannot silently go out message-less.
pub const DOCUMENTED_ERROR_MESSAGES: &[(&str, &str)] = &[
    // [ErrorCodeList]
    ("AccessDenied", "Access Denied"),
    (
        "AnnotationLimitExceeded",
        "The request would exceed the maximum number of annotations allowed per object.",
    ),
    // The sentence S3 answers this code with, as recorded behaviour words it: fixed text
    // that states the rule rather than the bound (the model's own documentation of the shape
    // states the bound, and is not what reaches the wire).
    ("AnnotationNameTooLong", "Your annotation name is too long."),
    // [ErrorCodeList]
    (
        "BucketAlreadyExists",
        "The requested bucket name is not available. The bucket namespace is shared by all \
         users of the system. Please select a different name and try again.",
    ),
    // [ErrorCodeList]
    (
        "BucketAlreadyOwnedByYou",
        "Your previous request to create the named bucket succeeded and you already own it.",
    ),
    (
        "EncryptionTypeMismatch",
        "The existing object was created with a different encryption type. Subsequent write \
         requests must include the appropriate encryption parameters in the request or while \
         creating the session.",
    ),
    (
        "IdempotencyParameterMismatch",
        "Parameters on this idempotent request are inconsistent with parameters used in \
         previous request(s).",
    ),
    ("InvalidAnnotationName", "The annotation name you provided is invalid."),
    (
        "InvalidObjectState",
        "Object is archived and inaccessible until restored.",
    ),
    // The sentence S3 sends on the wire for this code reads "you have provided", where the
    // model's prose for the same shape reads "you provided"; what a client sees is the
    // former, so that is the text this catalog carries.
    ("InvalidPrefix", "The annotation prefix you have provided is invalid."),
    (
        "InvalidRequest",
        "A parameter or header in your request isn't valid. For details, see the description \
         of this API operation.",
    ),
    (
        "InvalidWriteOffset",
        "The write offset value that you specified does not match the current object size.",
    ),
    (
        "NoSuchAnnotation",
        // The sentence S3's error document carries for this code, which states the
        // condition alone; the model's own prose for the shape adds a trailing clause
        // ("… on this object") that the service does not send.
        "The specified annotation does not exist.",
    ),
    // [ErrorCodeList], and the same text the unmodeled channel already sends for these
    // two codes on the subresource operations whose model declares no error shape —
    // reused from `state` so one code cannot answer two different messages.
    (
        crate::state::NO_SUCH_BUCKET_CODE,
        crate::state::NO_SUCH_BUCKET_MESSAGE,
    ),
    // [ErrorCodeList]
    (
        crate::state::NO_SUCH_KEY_CODE,
        crate::state::NO_SUCH_KEY_MESSAGE,
    ),
    (
        "NoSuchUpload",
        // The sentence S3 sends on the wire for this code. It states the same condition as
        // the `ErrorCodeList` entry and the model's own prose for the shape, which both
        // word it with the "multipart" qualifier ("The specified multipart upload does not
        // exist. The upload ID might be invalid, …"); what the service actually sends names
        // the upload alone, and the sent text is the contract a message-matching client
        // keys on.
        "The specified upload does not exist. The upload ID may be invalid, or the upload \
         may have been aborted or completed.",
    ),
    ("NotFound", "The specified content does not exist."),
    (
        "ObjectAlreadyInActiveTierError",
        "This action is not allowed against this storage tier.",
    ),
    (
        "ObjectNotInActiveTierError",
        "The source object of the COPY action is not in the active tier and is only stored in \
         Amazon S3 Glacier.",
    ),
    (
        "TooManyParts",
        "You have attempted to add more parts than the maximum of 10000 that are allowed for \
         this object. You can use the CopyObject operation to copy this object to another and \
         then add more data to the newly copied object.",
    ),
    (
        "UnsupportedMediaType",
        "The annotation payload is not valid UTF-8 encoded text.",
    ),
];

/// The documented `<Message>` for a wire error code, or `None` for a code
/// [`DOCUMENTED_ERROR_MESSAGES`] does not name.
pub fn documented_error_message(code: &str) -> Option<&'static str> {
    DOCUMENTED_ERROR_MESSAGES
        .iter()
        .find(|(candidate, _)| *candidate == code)
        .map(|(_, message)| *message)
}

/// The wire error codes a refusal of which MUST name the bucket it is about
/// ([`Scaffolded::naming_bucket`]).
///
/// Each one states a condition of a bucket — the bucket itself, or one of the bucket-level
/// subresources a `?`-addressed operation reads and writes — so the bucket is what the
/// refusal is ABOUT, and S3's document for it carries a `<BucketName>` beside the code and
/// the message. A client that fans one operation out over many buckets, or that logs and
/// retries per bucket, reads which bucket failed from there, and an SDK error object
/// surfaces it as `BucketName`.
///
/// Source: the elements S3's own error document carries for these conditions (Amazon S3 API
/// Reference, *Error responses*, whose `<Error>` document is `Code`, `Message`, the
/// condition's own contextual elements, `RequestId` and `HostId`). It cannot come from the
/// model: every error shape in `com.amazonaws.s3` declares NO members at all
/// (`smithy_query(query="shape",shape="NoSuchBucket,BucketAlreadyOwnedByYou,…",
/// model_path="services/service-com-amazonaws-s3-amazons3/smithy-model/com-amazonaws-s3-amazons3.json")`
/// reports `members: {}` for each), which is the same reason the `<Message>` above is a
/// catalog here rather than a member a handler fills — and why the name is attached to the
/// refusal itself ([`ErrorDetail`]) instead.
///
/// Three families are deliberately NOT here, because the condition each states is not a
/// bucket's:
///
/// * the OBJECT-scoped not-found codes ([`crate::state::NO_SUCH_KEY_CODE`],
///   [`crate::state::NO_SUCH_VERSION_CODE`], `NoSuchUpload`,
///   [`crate::state::NO_SUCH_OBJECT_LOCK_CONFIGURATION_CODE`]), whose document names the
///   key, the version or the upload that was not there — the first two through
///   [`OBJECT_SCOPED_ERROR_CODES`];
/// * the AUTHENTICATION and AUTHORIZATION refusals
///   ([`crate::state::ACCESS_DENIED_CODE`], the SigV4 refusals `service::sigv4` words),
///   which state something about the CALLER and are answered identically whichever bucket
///   was addressed; and
/// * the request-shape refusals ([`crate::state::INVALID_ARGUMENT_CODE`],
///   [`crate::state::MALFORMED_XML_CODE`], the scaffold's `NotImplemented`), which state
///   something about the request document.
///
/// Sorted by code, so a new row is easy to place;
/// `tests/all/bucket_error_envelope.rs` drives a request per row through the router and
/// fails if a row has none — which is what keeps a handler that answers one of these from
/// being written, or left, without [`Scaffolded::naming_bucket`].
pub const BUCKET_SCOPED_ERROR_CODES: &[&str] = &[
    // The bucket name is taken (by another account), and the bucket named is the one the
    // caller asked for.
    "BucketAlreadyExists",
    // The bucket exists and the caller already owns it.
    "BucketAlreadyOwnedByYou",
    crate::state::BUCKET_NOT_EMPTY_CODE,
    crate::state::NO_SUCH_BUCKET_CODE,
    crate::state::NO_SUCH_BUCKET_POLICY_CODE,
    crate::state::NO_SUCH_CORS_CONFIGURATION_CODE,
    crate::state::NO_SUCH_LIFECYCLE_CONFIGURATION_CODE,
    crate::state::NO_SUCH_PUBLIC_ACCESS_BLOCK_CONFIGURATION_CODE,
    crate::state::NO_SUCH_TAG_SET_CODE,
    crate::state::NO_SUCH_WEBSITE_CONFIGURATION_CODE,
    crate::state::OBJECT_LOCK_CONFIGURATION_NOT_FOUND_CODE,
    crate::state::OWNERSHIP_CONTROLS_NOT_FOUND_CODE,
    crate::state::REPLICATION_CONFIGURATION_NOT_FOUND_CODE,
];

/// Whether an error document carrying `code` is about the bucket the request addressed, so
/// a refusal that named no resource of its own is named by it — see
/// [`BUCKET_SCOPED_ERROR_CODES`].
pub fn names_its_bucket(code: &str) -> bool {
    BUCKET_SCOPED_ERROR_CODES.contains(&code)
}

/// Whether an error shape declares its OWN message member, in which case the handler's
/// value is what goes on the wire and nothing is written for it here.
///
/// No S3 error shape does today; this is what keeps the documented text from being
/// emitted beside a modeled one if the model ever gains it.
fn models_its_own_message(schema: &Schema) -> bool {
    schema.members().iter().any(|member| {
        member
            .member_name()
            .is_some_and(|name| name.eq_ignore_ascii_case("message"))
    })
}

